package in.finseq.insurance;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.net.URLEncoder;import java.time.LocalDate;
public class OrdersActivity extends FinseqActivity{
 LinearLayout list;Button fromButton,toButton,sync;LocalDate from=LocalDate.now().minusDays(30),to=LocalDate.now();boolean activeOnly=false;int customerId=0;TextView syncStatus;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=Ui.column(this);customerId=getIntent().getIntExtra("customer_id",0);Ui.appHeader(root,this,customerId>0?"Customer · My Orders":"Orders / SIP Activity");LinearLayout body=Ui.contentColumn(this);root.addView(body);fromButton=Ui.outlineButton(this,"From: "+from);toButton=Ui.outlineButton(this,"To: "+to);body.addView(fromButton);body.addView(toButton);fromButton.setOnClickListener(new View.OnClickListener(){public void onClick(View v){pick(true);}});toButton.setOnClickListener(new View.OnClickListener(){public void onClick(View v){pick(false);}});Button all=Ui.button(this,"All orders and SIPs");Button active=Ui.outlineButton(this,"Active client SIPs");body.addView(all);body.addView(active);all.setOnClickListener(new View.OnClickListener(){public void onClick(View v){activeOnly=false;load();}});active.setOnClickListener(new View.OnClickListener(){public void onClick(View v){activeOnly=true;load();}});sync=Ui.greenButton(this,"Sync selected dates + client SIPs from NSE");body.addView(sync);syncStatus=Ui.sub(this,"");body.addView(syncStatus);sync.setOnClickListener(new View.OnClickListener(){public void onClick(View v){sync();}});list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);setContentView(Ui.scroll(this,root));load();}
 void pick(final boolean start){LocalDate selected=start?from:to;new DatePickerDialog(this,new DatePickerDialog.OnDateSetListener(){public void onDateSet(DatePicker picker,int y,int m,int d){LocalDate value=LocalDate.of(y,m+1,d);if(start)from=value;else to=value;fromButton.setText("From: "+from);toButton.setText("To: "+to);load();}},selected.getYear(),selected.getMonthValue()-1,selected.getDayOfMonth()).show();}
 void load(){if(from.isAfter(to)){Ui.toast(this,"From date must be before To date");return;}Ui.run(this,new Runnable(){public void run(){try{String path="/api/v2/mf/activity?from="+URLEncoder.encode(from.toString(),"UTF-8")+"&to="+URLEncoder.encode(to.toString(),"UTF-8")+(activeOnly?"&active=1":"")+(customerId>0?"&customer_id="+customerId:"");final JSONArray rows=ApiClient.get(OrdersActivity.this,path).optJSONArray("activity");Ui.ui(OrdersActivity.this,new Runnable(){public void run(){render(rows);}});}catch(final Exception error){Ui.ui(OrdersActivity.this,new Runnable(){public void run(){Ui.toast(OrdersActivity.this,error.getMessage());}});}}});}
 void sync(){if(from.isAfter(to)||java.time.temporal.ChronoUnit.DAYS.between(from,to)>366){Ui.toast(this,"Select a range up to 367 days");return;}sync.setEnabled(false);syncStatus.setText("Syncing NSE orders and SIPs…");Ui.run(this,new Runnable(){public void run(){try{JSONObject request=new JSONObject().put("from",from.toString()).put("to",to.toString());final JSONObject result=ApiClient.post(OrdersActivity.this,"/api/v2/mf/activity/sync",request);Ui.ui(OrdersActivity.this,new Runnable(){public void run(){sync.setEnabled(true);JSONObject counts=result.optJSONObject("counts");syncStatus.setText("Synced "+(counts==null?0:counts.optInt("orders"))+" orders · "+(counts==null?0:counts.optInt("sip"))+" SIPs");load();}});}catch(final Exception error){Ui.ui(OrdersActivity.this,new Runnable(){public void run(){sync.setEnabled(true);syncStatus.setText("Sync failed: "+error.getMessage());}});}}});}
 void render(JSONArray rows){list.removeAllViews();if(rows==null){list.addView(Ui.sub(this,"No NSE data returned."));return;}int count=0;for(int i=0;i<rows.length();i++){final JSONObject x=rows.optJSONObject(i);if(x==null||activeOnly&&!x.optBoolean("active_sip"))continue;count++;LinearLayout card=Ui.card(this);final String category=x.optString("category","Activity");card.addView(Ui.text(this,category+" · "+x.optString("scheme_name"),16,true));card.addView(Ui.sub(this,x.optString("investor_name")+" · "+x.optString("client_code")));card.addView(Ui.sub(this,"Date: "+x.optString("date",x.optString("activity_date"))));card.addView(Ui.sub(this,"Status: "+x.optString("status")+" · NSE ID: "+x.optString("nse_id")));card.addView(Ui.text(this,Ui.money(x.optDouble("amount")),16,true));card.setOnClickListener(new View.OnClickListener(){public void onClick(View v){new AlertDialog.Builder(OrdersActivity.this).setTitle(category).setMessage("Client: "+x.optString("investor_name")+"\nUCC: "+x.optString("client_code")+"\nScheme: "+x.optString("scheme_name")+"\nDate: "+x.optString("activity_date")+"\nStatus: "+x.optString("status")+"\nSIP: "+x.optString("sip_reg_no")+"\nNSE ID: "+x.optString("nse_id")).setPositiveButton("Close",null).show();}});list.addView(card);if(count>=500)break;}list.addView(Ui.sub(this,count+" record(s) in selected view"),0);if(count==0)list.addView(Ui.sub(this,"No matching NSE activity. Sync the selected dates to refresh."));}
}
